  "implementation": "import math

def solve(case):
    matrix = case["matrix"]
    if not matrix or not matrix[0]:
        raise ValueError("Matrix must be nonempty and rectangular")
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    # Validate rectangular
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError("Matrix is not rectangular")
    # Compute document frequency per column
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # Compute IDF
    idf = []
    for j in range(n_cols):
        idf_val = math.log(1 + n_rows / (1 + df[j]))
        idf.append(round(idf_val, 6))
    # Build weighted matrix and row degrees
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = []
        total = 0.0
        for j, val in enumerate(row):
            w = val * idf[j]
            weighted_row.append(round(w, 6))
            total += w
        weighted_matrix.append(weighted_row)
        row_degree.append(round(total, 6))
    return {
        "idf": idf,
        "weighted_matrix": weighted_matrix,
        "row_degree": row_degree
    }"
}
